import path from "path";
import { fetchWithFallback } from "./api.js";
import { baseCacheKey, hasFolderCache, loadCacheJson, saveCacheJson } from "./cache.js";
import { getAssetsDir } from "./sync.js";
import {
  CONFIG_SERVERS,
  CONTENT_SYNC_FUNCTIONS,
} from "./config.js";
import { fileURLToPath } from "url";
import { dir, log } from "console";
import { baseConfigType, folderType } from "./types/base.type.js";
import {
  CallbackType,
  checkBaseJsonType,
  GenericInterface,
} from "./types/main.type.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PLATFORM_NAMES: Record<string, string> = {
  win32: "windows",
  darwin: "macos",
  linux: "linux",
};

async function fetchBaseJson(folder: string) {
  const url = CONFIG_SERVERS["base"];
  const localPath = path.join(__dirname, `../${folder}/Base.json`);
  console.log(url,"jfiuhgfuigfyu");

  return await fetchWithFallback(url, localPath);
}

function checkSigningMode(
  baseConfig: baseConfigType | null,
  appVersion: string,
  platform: string,
): { showDynamicContent: boolean; gateReason: string } {
  const currentPlatformName = PLATFORM_NAMES[platform] || platform;

  // "Find current platform object" - matching both type and app-version
  const platformEntry =
    baseConfig != null
      ? (baseConfig["signing-mode"] || []).find(
          (entry) =>
            entry.type === currentPlatformName &&
            entry["app-version"] === appVersion,
        )
      : null;

  /*
  const platformEntry = (baseConfig["signing-mode"] || []).find(
    (entry) => entry.type === currentPlatformName
  );

  if (!platformEntry) {
    // No signing-mode entry exists for this platform at all - nothing to gate on.
    return { showDynamicContent: true, gateReason: "no-signing-mode-entry-for-platform" };
  }

  // "App Version matches?"
  if (platformEntry["app-version"] !== appVersion) {
    // "No -> Do Nothing": this entry is for a different build than the one
    // currently running, so it has no effect on what we show.
    return { showDynamicContent: true, gateReason: "signing-mode-entry-is-for-a-different-app-version" };
  }
  */

  if (platformEntry && platformEntry.enabled === true) {
    // "Hide dynamic content and show default UI"
    return {
      showDynamicContent: false,
      gateReason: "signing-mode-enabled-hide-dynamic-content",
    };
  }

  // "Show downloaded dynamic content"
  return {
    showDynamicContent: true,
    gateReason: "signing-mode-disabled-show-dynamic-content",
  };
}

function finish(
  baseConfig: baseConfigType | null,
  appVersion: string,
  platform: string,
  pathReason: string,
  dirpath: string | null,
) {
  const gate = checkSigningMode(baseConfig, appVersion, platform);
  return {
    showDynamicContent: gate.showDynamicContent,
    useDefaultUI: !gate.showDynamicContent,
    baseConfig,
    reason: `${pathReason} | ${gate.gateReason}`,
    filePath: dirpath,
  };
}

async function downloadEverything(
  folder: folderType,
  latestBaseConfig: baseConfigType | null,
): Promise<string | null> {
  await saveCacheJson(baseCacheKey(folder), latestBaseConfig);
  // Download that folder's own content json (Notification.json / Payment.json /
  // onboarding.json) plus its assets. These sync functions already exist in
  // targeting.js and already do their own asset downloading

  const syncContent = CONTENT_SYNC_FUNCTIONS[folder];
  if (syncContent) {
    const result = await syncContent();

    if (!result) return null;

    return result.location || getAssetsDir(folder);
  } else {
    return null;
  }
}

async function checkBaseJson(
  folder: folderType,
  appVersion = "3.0.1",
  platform = "win",
  useCacheOnly = false,
): Promise<checkBaseJsonType | null>{
  const cachedBase = (await loadCacheJson(
    baseCacheKey(folder),
  )) as baseConfigType | null;

  if (useCacheOnly) {
    if (!cachedBase) {
      return {
        showDynamicContent: false,
        useDefaultUI: true,
        baseConfig: null,
        reason: "cache-only-no-cache",
        filePath: null,
      };
    }
    return finish(cachedBase, appVersion, platform, "cache-only", null);
  }

  // "Fetch base.json"
  let latestBase: baseConfigType | null = null;
  try {
    latestBase = (await fetchBaseJson(folder)) as baseConfigType;
  } catch (err) {
    // fetch error
  }

  // ---- "Error" branch ----
  if (!latestBase) {
    if (!cachedBase) {
      // "Cached base.json? -> No -> Use Default UI"
      return {
        showDynamicContent: false,
        useDefaultUI: true,
        baseConfig: null,
        reason: "fetch-failed-no-cache",
        filePath: null,
      };
    }
    // "Cached base.json? -> Yes -> Use Cached base.json"
    return finish(
      cachedBase,
      appVersion,
      platform,
      "fetch-failed-used-cache",
      null,
    );
  }

  // ---- "Success" branch ----

  let dirpath: string | null = null;
  // "Already Cached? -> No"

  // const NoneedsDownload = hasFolderCache(folder);



  // if (!NoneedsDownload){
    dirpath = await downloadEverything(folder, latestBase);
  // }

  if(!dirpath)return null;

  // "Already Cached? -> Yes -> Compare Base Version"
  const cachedBaseLocalVersion =
    cachedBase != null ? cachedBase["api-base-local-version"] : null;
  const downloadedBaseLocalVersion =
    latestBase != null ? latestBase["api-base-local-version"] : null;

  if (String(cachedBaseLocalVersion) !== String(downloadedBaseLocalVersion)) {
    dirpath = await downloadEverything(folder, latestBase);

    return finish(
      latestBase,
      appVersion,
      platform,
      "base-version-changed",
      dirpath,
    );
  }

  return finish(
    latestBase,
    appVersion,
    platform,
    "already-up-to-date",
    dirpath,
  );
}

function generic({ interval, tillTime, callback, type }: GenericInterface) {
  if (
    !Number.isFinite(interval) ||
    (tillTime !== null && !Number.isFinite(tillTime))
  ) {
    throw new TypeError("interval and tillTime must be numbers (ms)");
  }

  if (interval < MIN_INTERVAL_TIME) {
    throw new RangeError(
      `interval must be greater than ${MIN_INTERVAL_TIME}'s ms.`,
    );
  }

  if (tillTime !== null && tillTime < MIN_INTERVAL_TIME) {
    throw new RangeError(
      `Till time must be greater than ${MIN_INTERVAL_TIME}'s ms`,
    );
  }

  if (typeof callback !== "function") {
    throw new TypeError("callback must be a function");
  }
  if (tillTime !== null && interval >= tillTime) {
    throw new RangeError("interval must be less than tillTime");
  }

  let stopped: boolean = false;
  let timer: undefined | ReturnType<typeof setTimeout>;
  const endTime = tillTime === null ? null : Date.now() + tillTime + 10000;

  const stop = () => {
    if (stopped) return;
    stopped = true;
    clearTimeout(timer);
    log(`${type} polling ended`);
    callback(null, null, false);
  };

  const tick = async () => {
    if (stopped) {
      callback(null, null, false);
      return;
    }
    if (endTime !== null && Date.now() >= endTime) {
      stop();
      return;
    }

    let dir: null | string = null;
    let error: Error | null = null;
    let Active: boolean = false;

    try {
      const dirPath = await checkBaseJson(type);
      dir = dirPath != undefined ? dirPath.filePath : null;

      Active = dir != null ? true : false;
    } catch (err: unknown) {
      error = err instanceof Error ? err : new Error(String(err));
    }
    if (stopped) {
      callback(null, dir, false);
      return;
    }
    try {
      if (type !== "notification" || error || dir) {
        callback(error, dir, Active);
      }
    } catch (err: unknown) {
      stop();
      console.error(` ${type} callback error`, err);
    }

    if (!stopped) timer = setTimeout(tick, interval);
  };
  log(`${type} polling started, at every ${interval}'s ms till ${tillTime}`);

  tick().catch((err) => {
    stop();
    console.error(`${type} poller crashed`, err);
  });

  return stop;
}

const MIN_INTERVAL_TIME = 30000;

interface mainParameterType {
  interval: number;
  tilltime: number;
}

const onBoarding = (
  interval: number,
  tillTime: number,
  callback: CallbackType,
) => {
  return generic({ interval, tillTime, callback, type: "onboarding" });
};

const notification = async () => {
  const dirPath = await checkBaseJson("notification");
  if(!dirPath)return null;

  return dirPath.filePath;
};

const payment = (
  interval: number,
  tillTime: number,
  callback: CallbackType,
) => {
  return generic({ interval, tillTime, callback, type: "payment" });
};

export { onBoarding, notification, payment, checkBaseJson };
